def direct_repeats(s, minlen=15, maxlen=60):
    found={}
    n=len(s)
    for i in range(n):
        for j in range(i+minlen, n):
            l=0
            while j+l<n and s[i+l]==s[j+l] and l<maxlen:
                l+=1
            if l>=minlen:
                key=s[i:i+minlen]
                # record
                found.setdefault((i,j),l)
    return found

