L=len(seq)
comp={"A":"T","T":"A","G":"C","C":"G"}
def rc(s): return "".join(comp[c] for c in reversed(s))
def translate(s):
    code = {'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L','ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V','TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P','ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A','TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
    return "".join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))
def maxorf(s):
    best=0
    for st in (s, rc(s)):
        for fr in range(3):
            p=translate(st[fr:]); i=0
            while i<len(p):
                if p[i]=='M':
                    j=p.find('*',i)
                    if j==-1: j=len(p)
                    best=max(best,j-i); i=j
                else: i+=1
    return best
